\documentclass{article}
\usepackage[dvipsnames]{xcolor}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows} %% Can be useful, not essential
\usetikzlibrary{intersections} %% Can be useful, not essential
\usepgfplotslibrary{fillbetween} %% Can be useful, not essential
\begin{document}
\pagestyle{empty} %% IMPORTANT
\begin{tikzpicture}

% Axis
\draw[line width=0.3mm] (-3.5,0) -- (5.5,0);
\foreach \i in {-3,...,5} % numbers on line 
{
	\draw[black, line width=0.2pt] (\i,0.1) -- + (0,-0.2) node[below] {\small $\i$};
}

% Clip
\def\mycolor{blue!40};
\def\myh{1.6};
\def\myhm{-0.75};
\def\myopacity{0.25};
\draw[draw=none, fill opacity=\myopacity, shading=axis, left color=white, right color=\mycolor, shading angle=180, anchor=north] (-1,0) rectangle (3,\myhm);
\draw[draw=none, fill opacity=\myopacity, shading=axis, left color=white, right color=\mycolor, shading angle=0, anchor=north] (-1,\myh) rectangle (3,0);

\draw[gray, dashed, thin] (-1,0) -- (-1,0.5);
\draw[gray, dashed, thin] (3,0) -- (3,1);

\draw[red, line width=0.5mm, ->] (-1,0.5) -- (5.5,0.5);
\node[circle,draw=none,fill=red,inner sep=2pt] at (-1,0.5) {};

\draw[red, line width=0.5mm,->] (3,1) -- (-3.5,1);
\node[circle,thick,draw=red,fill=white,inner sep=2pt] at (3,1) {};

\draw[blue, line width=0.5mm,-] (-1,0) -- (3,0); 
\node[circle,thick,draw=none,fill=blue,inner sep=2pt] at (-1,0) {};
\node[circle,thick,draw=blue,fill=white,inner sep=2pt] at (3,0) {};

\end{tikzpicture}
\end{document}

